#include "stdafx.h"

// =============================================================================
//  LocalizationPT.cpp    The Hell 4 -- Portuguese (Brazilian) overlay
//  LANG_PT = 3. Latin script: plain C string literals (Latin-1). The accented
//  glyphs (a-acute, a-tilde, c-cedilla, ...) live in the shipped datafile
//  TH4loc_prt.mor (smaltext/medtexts/bigtgold.cel), mounted only when the active
//  language is PT (Windows.cpp). This file owns ONLY the Portuguese tables + the
//  registry getters that Localization.cpp / Traits.cpp / Hell.cpp dispatch to.
//
//  STATUS: SCAFFOLD. All tables are empty for now -> every string falls back to
//  English automatically. The purpose of this pass is to wire the language end to
//  end (enum, config index 3, datafile mount, overlay registry, dispatch branches)
//  so the datafile can be verified in-game. Translations are added afterwards, the
//  same way LocalizationID.cpp was populated: add { "English key", "Portuguese" }
//  rows to the tables below (keys must byte-exactly match the English source
//  literal) and fill the per-id getters. English source & the RU/ID tables are
//  never touched here.
//
//  To ADD A TABLE ROW later: put it in the matching PT_* array; the getter already
//  returns that array, so registration is automatic. Non-ASCII (accented) bytes are
//  fine as raw Latin-1 in the literal (read/write this file with encoding='latin-1').
// =============================================================================

struct UiStr  { const char* en; const char* pt; }; // .pt column holds the PT text
struct IdxStr { int index; const char* tr; };

enum {
	OVL_UI = 0, OVL_MENU, OVL_UNIQUE_ITEM, OVL_AFFIX_PREFIX, OVL_AFFIX_SUFFIX,
	OVL_BASE_ITEM, OVL_BASE_NAME2, OVL_ELEMENT, OVL_SPICIES, OVL_ICEAGE,
	OVL_SPELL, OVL_SPELL_NOM, OVL_PERK_NAME, OVL_PERK_DESC, OVL_WARP,
	OVL_STR_COUNT
};
enum { OVL_SPEECH = 0, OVL_ONSCREEN, OVL_QUEST, OVL_IDX_COUNT };

// -----------------------------------------------------------------------------
//  String-keyed overlay tables (empty scaffold). Add { "en", "pt" } rows here.
//  Each array must have at least one element to be a valid array; the getters
//  below report a count of 0 while the tables are empty (the sole placeholder row
//  has a NULL English key that never matches), so nothing registers and English
//  is used everywhere. Replace the placeholder row with real rows to populate.
// -----------------------------------------------------------------------------
// In-game ESC menu (custom BigTGold menu engine). menu.cpp draws these via
// L("...") which resolves through OVL_UI, so they belong in PT_Ui (NOT PT_Menu).
// Accent-free on purpose for this first test: these render from the plain ASCII
// glyphs already present in bigtgold.cel. Accented variants (Opcoes, etc.) wait
// until the BIG-font accent frames are mapped.
