// Count helper: report 0 while a table holds only the placeholder row, so an
// empty table registers nothing (English fallback). Once real rows are added the
// count reflects the true size. Placeholder = NULL English key / negative index.
static bool isPlaceholder( const UiStr&  r ) { return r.en == 0; }
static bool isPlaceholder( const IdxStr& r ) { return r.index < 0 && r.tr == 0; }

template<typename T, size_t N>
static int countRows( const T (&arr)[N] )
{
	if( N == 1 && isPlaceholder( arr[0] ) ) return 0;
	return (int)N;
}

const UiStr* PT_GetStrTable( int ovlId, int* n )
{
	switch( ovlId ){
		case OVL_UI:           *n = countRows(PT_Ui);          return PT_Ui;
		case OVL_MENU:         *n = countRows(PT_Menu);        return PT_Menu;
		case OVL_UNIQUE_ITEM:  *n = countRows(PT_UniqueItem);  return PT_UniqueItem;
		case OVL_AFFIX_PREFIX: *n = countRows(PT_AffixPrefix); return PT_AffixPrefix;
		case OVL_AFFIX_SUFFIX: *n = countRows(PT_AffixSuffix); return PT_AffixSuffix;
		case OVL_BASE_ITEM:    *n = countRows(PT_BaseItem);    return PT_BaseItem;
		case OVL_BASE_NAME2:   *n = countRows(PT_BaseName2);   return PT_BaseName2;
		case OVL_ELEMENT:      *n = countRows(PT_Element);     return PT_Element;
		case OVL_SPICIES:      *n = countRows(PT_Spicies);     return PT_Spicies;
		case OVL_ICEAGE:       *n = countRows(PT_IceAge);      return PT_IceAge;
		case OVL_SPELL:        *n = countRows(PT_Spell);       return PT_Spell;
		case OVL_SPELL_NOM:    *n = countRows(PT_SpellNom);    return PT_SpellNom;
		case OVL_PERK_NAME:    *n = countRows(PT_PerkName);    return PT_PerkName;
		case OVL_PERK_DESC:    *n = countRows(PT_PerkDesc);    return PT_PerkDesc;
		case OVL_WARP:         *n = countRows(PT_Warp);        return PT_Warp;
	}
	*n = 0; return 0;
}

const IdxStr* PT_GetIdxTable( int ovlId, int* n )
{
	switch( ovlId ){
		case OVL_SPEECH:   *n = countRows(PT_Speech);   return PT_Speech;
		case OVL_ONSCREEN: *n = countRows(PT_OnScreen); return PT_OnScreen;
		case OVL_QUEST:    *n = countRows(PT_Quest);    return PT_Quest;
	}
	*n = 0; return 0;
}

